\immini[thm]{
Cho hình bình hành  ${QKHG}$ có ${F, E}$ lần lượt là trung điểm của ${QK, HG }$. Đường ${QE}$ và ${HF}$ cắt ${KG}$ lần lượt tại ${I, J }$.

 a) Chứng minh rằng ${ QFHE }$ là hình bình hành,

 b) Từ ${J}$ kẻ đường thẳng song song với ${QK}$ cắt ${QE}$ tại ${O}$. Chứng minh $KJ=IJ=IG$
}{
\begin{tikzpicture}
            \coordinate (A) at (-3, 0);
            \coordinate (D) at (2, 0);
            \coordinate (C) at (3, 2);
            \coordinate (B) at (-2, 2);
           \coordinate (E) at (0.67, 0.67);
            \coordinate (M) at (-2.5, 1);
             \coordinate (N) at (2.5, 1);
              \coordinate (F) at (-0.67, 1.33);
              \coordinate (G) at (-1.17, 0.33);
            % Vẽ tứ giác
            \draw[thick] (M) -- (C);
            \draw[thick] (A) -- (B) -- (C) -- (D) -- (A);
        \draw[thick] (A) -- (N);
        \draw[thick] (B) -- (D);
         \draw[thick] (F) -- (G);
            % Ghi nhãn các điểm
            \node[above left] at (M) {$F$};
            \node[above left] at (B) {$K$};
            \node[above right] at (C) {$H$};
            \node[below right] at (D) {$G$};
            \node[above left] at (A){$Q$};
            \node[above right] at (N) {$E$};
            \node[below] at (E) {$I$};
             \node[above] at (F) {$J$};
                \node[above right] at (G) {$O$};
    \end{tikzpicture}
}
\loigiai{ 
 a) Ta có $\dfrac{1}{2}QK=\dfrac{1}{2}HG =FK=FQ=EH=EG $

 và $QF//HE$ nên tứ giác ${ QFHE }$ là hình bình hành.

b) Tứ giác ${QFJO }$ có $QF//OJ, FJ//QO$ nên là hình bình hành suy ra $QF=OJ=FK$ 

 Lại có $\widehat{JOI} =\widehat{FQO}$ (2 góc đồng vị) và $\widehat{KFJ} =\widehat{FQO}$(đồng vị)

  $\Rightarrow \widehat{JOI}= \widehat{KFJ}$ 

 $\Delta {KFJ}=\Delta{JOI } $ (g-c-g) $\Rightarrow KJ=IJ $ 

 Chứng minh tương tự $\Delta {IJO}=\Delta {IGE }$  (g-c-g) $\Rightarrow IJ=IG $ 

 Vậy $KJ=IJ=IG$ 
 }\end{ex}

