\begin{ex}%[8H9V3]
\immini[thm]{
Cho biết chiếc thang của một xe cứu hỏa có chiều dài $AB = 13$ m, chân thang cách mặt đất một khoảng $BE = 2,2$ m và cách tường tòa nhà một khoảng $BC = 5$ m. Tính chiều cao $AD$ mà thang có thể vươn tới (kết quả làm tròn đến hàng phần mười).
}{
\begin{tikzpicture}[line cap=round, line join=round, scale=0.3]
    % Định nghĩa các điểm (Dùng b_val để tính toán tọa độ)
    \coordinate (E) at (0,0);
    \coordinate (D) at (5,0);
    \coordinate (B) at (0,2.2);
    \coordinate (C) at (5,2.2);
    \coordinate (A) at (5, 14.2);

    % Vẽ các đoạn thẳng
    \draw[thick] (A) -- (B) node[midway, left, xshift=-2pt] {13m};
    \draw[thick] (B) -- (C) node[midway, above] {5m};
    \draw[thick] (A) -- (D);
    \draw[thick] (B) -- (E) node[midway, left] {2,2m}; % Hiển thị dấu phẩy ở đây
    \draw[thick] (E) -- (D);

    % Ký hiệu góc vuông tại C
    \draw (4.2, 2.2) -- (4.2, 3.0) -- (5, 3.0);

    % Gán nhãn các đỉnh
    \node[above] at (A) {$A$};
    \node[left] at (B) {$B$};
    \node[right] at (C) {$C$};
    \node[below] at (D) {$D$};
    \node[below] at (E) {$E$};
\end{tikzpicture}
}
\loigiai{ 
 Xét tứ giác $BCDE$ có $\widehat{E} = \widehat{D} = \widehat{C} = 90^\circ$ nên $BCDE$ là hình chữ nhật. Suy ra $CD = BE = 2,2$ m.

Áp dụng định lý Pythagore cho $\Delta ABC$ vuông tại $C$, ta có:
$AC^2 = AB^2 - BC^2 = 13^2 - 5^2 = 144$.
$\Rightarrow AC = \sqrt{144} \approx 12,0$ (m).

Chiều cao mà thang có thể vươn tới là:
$AD = AC + CD \approx 12,0 + 2,2 = 14,2$ (m).
Vậy chiều cao mà thang có thể vươn tới khoảng $14,2$ m. 
 }\end{ex}

